package com.shivhub.backend.controller;
import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import com.shivhub.backend.dto.DistributorCreditNoteRequest; import com.shivhub.backend.entity.User; import com.shivhub.backend.repository.UserRepository; import com.shivhub.backend.service.DistributorCreditNoteService; import lombok.RequiredArgsConstructor;
@RestController @RequestMapping("/api/distributor-credit-notes") @CrossOrigin(origins="*") @RequiredArgsConstructor public class DistributorCreditNoteController { private final DistributorCreditNoteService service; private final UserRepository users; private User seller(Authentication a){return users.findByEmail(a.getName()).orElseThrow(()->new RuntimeException("Seller not found"));} @GetMapping public List<Map<String,Object>> list(Authentication a){return service.list(seller(a));} @PostMapping public ResponseEntity<?> add(Authentication a,@RequestBody DistributorCreditNoteRequest r){try{return ResponseEntity.status(HttpStatus.CREATED).body(service.add(r,seller(a)));}catch(RuntimeException e){return ResponseEntity.badRequest().body(Map.of("message",e.getMessage()));}} }
